import React, { useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { predictionAPI } from "../services/api";

const INITIAL = {
  gender: "", age: "", hypertension: "", heart_disease: "",
  ever_married: "", work_type: "", residence_type: "",
  avg_glucose_level: "", bmi: "", smoking_status: "",
};

// ── Defined OUTSIDE the component so React never recreates them ──────────────
// This is the root cause of the focus-loss bug: components defined inside a
// parent function are treated as new component types on every render, which
// forces React to unmount+remount them, losing focus after each keystroke.

const FormGroup = ({ label, children }) => (
  <div className="form-group">
    <label>{label}</label>
    {children}
  </div>
);

const SelectField = ({ label, name, value, onChange, options }) => (
  <FormGroup label={label}>
    <select
      className="form-control"
      name={name}
      value={value}
      onChange={onChange}
      required
    >
      <option value="">Select…</option>
      {options.map(([v, l]) => (
        <option key={v} value={v}>{l}</option>
      ))}
    </select>
  </FormGroup>
);

const NumberField = ({ label, name, value, onChange, step, min, max }) => (
  <FormGroup label={label}>
    <input
      className="form-control"
      type="number"
      name={name}
      value={value}
      onChange={onChange}
      step={step || 1}
      min={min}
      max={max}
      required
      autoComplete="off"
    />
  </FormGroup>
);

// ── Main component ────────────────────────────────────────────────────────────
export default function PredictPage() {
  const [form, setForm] = useState(INITIAL);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  // useCallback keeps the same function reference across renders
  const handleChange = useCallback((e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      const { data } = await predictionAPI.submit(form);
      navigate("/patient/result", {
        state: { result: data.result, probability: data.probability, inputData: form },
      });
    } catch (err) {
      setError(err.response?.data?.message || "Prediction failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page">
      <Navbar />
      <main className="container main-content">
        <div style={{ maxWidth: 700, margin: "0 auto" }}>
          <h1 style={{ fontSize: "1.5rem", fontWeight: 700, marginBottom: ".3rem" }}>
            Stroke Risk Assessment
          </h1>
          <p style={{ color: "var(--text-muted)", marginBottom: "1.5rem", fontSize: ".9rem" }}>
            Fill in your health details below. The ML model will analyse your risk level.
          </p>

          {error && <div className="alert alert-error">{error}</div>}

          <div className="card">
            <form onSubmit={handleSubmit}>

              {/* ── Personal Information ── */}
              <h4 style={{ marginBottom: "1rem", color: "var(--text-muted)", fontSize: ".85rem", textTransform: "uppercase", letterSpacing: ".06em" }}>
                Personal Information
              </h4>

              <div className="form-row">
                <SelectField
                  label="Gender" name="gender" value={form.gender} onChange={handleChange}
                  options={[["male","Male"],["female","Female"],["other","Other"]]}
                />
                <NumberField
                  label="Age" name="age" value={form.age} onChange={handleChange}
                  min={0} max={120}
                />
              </div>

              <div className="form-row">
                <SelectField
                  label="Ever Married?" name="ever_married" value={form.ever_married} onChange={handleChange}
                  options={[["yes","Yes"],["no","No"]]}
                />
                <SelectField
                  label="Work Type" name="work_type" value={form.work_type} onChange={handleChange}
                  options={[
                    ["Private","Private"],
                    ["Self-employed","Self-employed"],
                    ["Government job","Government Job"],
                    ["Children","Children"],
                    ["Never Worked","Never Worked"],
                  ]}
                />
              </div>

              <SelectField
                label="Residence Type" name="residence_type" value={form.residence_type} onChange={handleChange}
                options={[["urban","Urban"],["rural","Rural"]]}
              />

              <hr style={{ margin: "1.2rem 0", borderColor: "var(--border)" }} />

              {/* ── Medical Information ── */}
              <h4 style={{ marginBottom: "1rem", color: "var(--text-muted)", fontSize: ".85rem", textTransform: "uppercase", letterSpacing: ".06em" }}>
                Medical Information
              </h4>

              <div className="form-row">
                <SelectField
                  label="Hypertension" name="hypertension" value={form.hypertension} onChange={handleChange}
                  options={[["1","Yes"],["0","No"]]}
                />
                <SelectField
                  label="Heart Disease" name="heart_disease" value={form.heart_disease} onChange={handleChange}
                  options={[["1","Yes"],["0","No"]]}
                />
              </div>

              <div className="form-row">
                <NumberField
                  label="Average Glucose Level (mg/dL)" name="avg_glucose_level"
                  value={form.avg_glucose_level} onChange={handleChange}
                  step="0.01" min={50} max={400}
                />
                <NumberField
                  label="BMI" name="bmi" value={form.bmi} onChange={handleChange}
                  step="0.1" min={10} max={60}
                />
              </div>

              <SelectField
                label="Smoking Status" name="smoking_status" value={form.smoking_status} onChange={handleChange}
                options={[
                  ["never smoked","Never Smoked"],
                  ["formerly smoked","Formerly Smoked"],
                  ["smokes","Smokes"],
                  ["unknown","Unknown"],
                ]}
              />

              <button
                className="btn btn-primary btn-block"
                type="submit"
                disabled={loading}
                style={{ marginTop: "1rem" }}
              >
                {loading
                  ? <><span className="spinner"></span> Analysing… (ML model running)</>
                  : "🔍 Predict Stroke Risk"}
              </button>
            </form>
          </div>

          <div className="alert alert-warning" style={{ marginTop: "1rem", fontSize: ".85rem" }}>
            ⚠️ This tool is for informational purposes only and does not constitute medical advice.
          </div>
        </div>
      </main>
    </div>
  );
}
